import 'package:flutter/material.dart';import '../data/app_store.dart';import '../models/models.dart';import '../widgets/common.dart';
class HandoverScreen extends StatelessWidget{final AppStore store;const HandoverScreen({super.key,required this.store});@override Widget build(BuildContext c){final open=store.tasks.where((x)=>x.state!=ActionState.completed).toList();final maint=store.equipment.where((x)=>x.state==EquipmentState.maintenance||x.state==EquipmentState.outOfService||x.state==EquipmentState.taggedOut).toList();return Scaffold(appBar:AppBar(title:const Text('Shift handover')),body:ListView(children:[const SectionLabel('Open actions'),...open.map((e)=>ListTile(title:Text(e.title),subtitle:Text(e.equipmentTag??'General'))),const SectionLabel('Equipment unavailable / maintenance'),...maint.map((e)=>ListTile(title:Text(e.tag),subtitle:Text('${e.name} · ${e.state.name}'))),const SectionLabel('Watch items'),...store.watch.where((e)=>e.active).map((e)=>ListTile(title:Text(e.equipmentTag??e.title),subtitle:Text('${e.title} · ${e.detail}'))),const SectionLabel('Recent shift activity'),...store.logs.take(10).map((e)=>ListTile(title:Text(e.text),subtitle:Text(hhmm(e.createdAt)))),const SizedBox(height:30)]));}}
